export const getExerciseTeaching = (exercise: Exercise): ExerciseTeaching => exerciseTeaching[exercise.id] ?? categoryTeaching[exercise.category] ?? {
  focus: `Sinta o trabalho em ${exercise.primary.toLowerCase()} e mantenha o movimento lento e confortável.`,
  cues: ['Mantenha o tronco estável e a amplitude sem dor.', 'Expire na parte mais difícil e inspire no retorno.', 'Reduza a carga ou a amplitude se perder a técnica.'],
};

const exerciseGifBase = 'https://cdn.jsdelivr.net/gh/JahelCuadrado/ExerciseGymGifsDB@v1.1.0';
const exerciseGifSource = 'https://jahelcuadrado.github.io/ExerciseGymGifsDB/';

const exerciseGif = (path: string, label: string): ExerciseGif => ({
  url: `${exerciseGifBase}/${path}.gif`,
  label,
  sourceUrl: exerciseGifSource,
  sourceLabel: 'Exercise Gym GIFs DB',
});

const youtubeSearch = (term: string): string => `https://www.youtube.com/results?search_query=${encodeURIComponent(`${term} execução correta vídeo curto`)}`;

const gifPair = (firstPath: string, firstLabel: string, secondPath: string, secondLabel: string, term: string): ExerciseMedia => ({
  gifs: [exerciseGif(firstPath, firstLabel), exerciseGif(secondPath, secondLabel)],
  youtubeUrl: youtubeSearch(term),
});

