export const weekdayFromDate = (date: Date): Weekday => {
  const values: Weekday[] = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sab'];
  return values[date.getDay()];
};

export const formatDate = (date: Date): string => new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short' }).format(date).replace('.', '');

export const formatFullDate = (date: Date): string => new Intl.DateTimeFormat('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' }).format(date);
